    /// Get today's reading based on the calendar day of the year
    static func todaysReading(startDate: Date = Calendar.current.date(from: DateComponents(year: Calendar.current.component(.year, from: Date()), month: 1, day: 1))!) -> DailyReading? {
        let dayOfYear = Calendar.current.ordinality(of: .day, in: .year, for: Date()) ?? 1
        let index = min(dayOfYear, 365) - 1
        guard index >= 0 && index < readings.count else { return nil }
        return readings[index]
    }
    
    /// Get reading for a specific day number (1-365)
    static func reading(forDay day: Int) -> DailyReading? {
        readings.first { $0.id == day }
    }
